import{_ as d,a0 as p,w as l,s as a,ao as i,I as e,a1 as s,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Root 是誰？為什麼會有 Root 賬户？ | LCTT x X-CMD","titleTemplate":false,"description":"Root 是誰？為什麼會有 Root 賬户？ | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Root 是誰？為什麼會有 Root 賬户？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Root 是誰？為什麼會有 Root 賬户？ | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170211 Who Is Root Why Does Root Exist","title":"Root 是誰？為什麼會有 Root 賬户？","tag":"201702","desc":""},"relativePath":"201702/20170211 Who Is Root Why Does Root Exist.md","filePath":"[post].md"}'),u={name:"201702/20170211 Who Is Root Why Does Root Exist.md"};function m(w,o,f,x,T,h){const r=p("Link");return l(),a("div",null,[o[25]||(o[25]=i('<h1 id="root-是誰-為什麼會有-root-賬户" tabindex="-1">Root 是誰？為什麼會有 Root 賬户？ <a class="header-anchor" href="#root-是誰-為什麼會有-root-賬户" aria-label="Permalink to “Root 是誰？為什麼會有 Root 賬户？”">​</a></h1><p>在 Linux 中為什麼會有一個名為 root 的特定賬户？該怎麼使用 root 賬户？它在哪些場景下必須使用，哪些場景下不能使用？對於以上幾個問題，如果您感興趣的話，那麼請繼續閲讀。</p><p>本文中，我們提供了一些關於 root 賬户的參考資料，方便您瞭解。</p><h3 id="root-是什麼" tabindex="-1">root 是什麼？ <a class="header-anchor" href="#root-是什麼" aria-label="Permalink to “root 是什麼？”">​</a></h3><p>首先，記住這一點，在 Unix 類操作系統中，目錄的層級結構被設計為樹狀結構。起始目錄是一個特殊目錄，使用斜槓 <code>/</code> 表示，而其他目錄都是由起始目錄分支而來。由於這種結構很像現實中的樹，所以 <code>/</code> 也被稱為根（root）目錄。</p><p>下圖，我們可以看到以下命令的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -d / | less</span></span></code></pre></div><p>該命令主要是演示一下 <code>/</code> 根目錄和樹<code>根</code>的類比。</p>',8)),e("p",null,[s(r,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Linux-root-Directory-Tree.png"},{default:n(()=>[...o[0]||(o[0]=[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Linux-root-Directory-Tree.png",alt:"Linux 的目錄層級"},null,-1)])]),_:1})]),o[26]||(o[26]=i('<p><em>Linux 的目錄層級</em></p><p>雖然 root 賬户命名的原因還不是很清楚，可能是因為 root 賬户是唯一一個在根目錄 <code>/</code> 中有寫權限的賬號吧。</p><p>此外，由於 root 賬户可以訪問 Unix 類操作系統中的所有文件和命令，因此，它也常被稱為超級用户。</p><p>另外，根目錄 <code>/</code> 和 <code>/root</code> 目錄不能混淆了，<code>/root</code> 目錄是 <code>root</code> 賬户的家目錄。實際上，<code>/root</code> 目錄是根目錄 <code>/</code> 的子目錄。</p><h3 id="獲取-root-權限" tabindex="-1">獲取 root 權限 <a class="header-anchor" href="#獲取-root-權限" aria-label="Permalink to “獲取 root 權限”">​</a></h3><p>當我們説到 root（或者超級用户）權限的時候，我們指的是這樣一種賬户的權限：其在系統上的權限包含（但不限於）修改系統並授權其他用户對系統資源的訪問權限。</p><p>胡亂使用 root 賬户，輕則系統崩潰重則系統完全故障。這就是為什麼會説，以下準則是使用 root 賬户的正確姿勢：</p><p>首先，使用 root 賬户運行 <code>visudo</code> 命令編輯 <code>/etc/sudoers</code> 文件，給指定賬户（如：<code>supervisor</code>）授予最低的超級用户權限。</p>',8)),e("p",null,[o[3]||(o[3]=t("最低超級用户權限可以包含，例如：",-1)),s(r,{href:"http://www.tecmint.com/add-users-in-linux/"},{default:n(()=>[...o[1]||(o[1]=[t("添加用户 (",-1),e("code",null,"adduser",-1),t(")",-1)])]),_:1}),o[4]||(o[4]=t("、",-1)),s(r,{href:"http://www.tecmint.com/usermod-command-examples/"},{default:n(()=>[...o[2]||(o[2]=[t("修改用户 (",-1),e("code",null,"usermod",-1),t(")",-1)])]),_:1}),o[5]||(o[5]=t("等權限。",-1))]),e("p",null,[o[7]||(o[7]=t("接着，使用 ",-1)),o[8]||(o[8]=e("code",null,"supervisor",-1)),o[9]||(o[9]=t(" 賬户登錄並",-1)),s(r,{href:"http://www.tecmint.com/sudoers-configurations-for-setting-sudo-in-linux/"},{default:n(()=>[...o[6]||(o[6]=[t("使用 ",-1),e("code",null,"sudo",-1),t(" 執行用户管理任務",-1)])]),_:1}),o[10]||(o[10]=t("。此時，你可能會發現，當你執行需要超級用户權限（例如：刪除軟件包）的其它任務時，會失敗。",-1))]),e("p",null,[s(r,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Run-Commands-Without-sudo.png"},{default:n(()=>[...o[11]||(o[11]=[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Run-Commands-Without-sudo.png",alt:"沒有使用超級用户權限運行命令"},null,-1)])]),_:1})]),o[27]||(o[27]=i('<p><em>沒有使用超級用户權限運行命令</em></p><p>在必須使用超級用户權限時，重複執行以上兩個步驟，一旦執行完成，則立即使用 <code>exit</code> 命令退回到無特限的賬户。</p><p>此時，你需要確定一下其他週期性的任務是否需要超級用户權限？如果需要，那麼在 <code>/etc/sudoers</code> 中，給指定的賬户或組授予必要的權限，儘量避免直接使用 <code>root</code> 賬户操作。</p><h5 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to “摘要”">​</a></h5><p>本文可以作為在 Unix 類操作系統中正確使用 root 賬户的簡單參考。收藏一下，你就可以隨時翻閲！</p><p>還是一樣，如果您對本文有什麼疑問或建議，請使用以下的評論表單給我們評論留言，期待您的迴音！</p><hr><p>作者簡介：</p><p>Gabriel Cánepa 來自 Villa Mercedes, San Luis, Argentina。他是一名 GNU/Linux 系統管理員和 Web 開發員，現在一家全球領先的消費品公司就職。他很喜歡使用 FOSS 工具來提高自己的工作效率。</p><hr>',10)),e("p",null,[o[13]||(o[13]=t("via: ",-1)),s(r,{href:"http://www.tecmint.com/who-is-root-why-does-root-exist-in-linux/"},{default:n(()=>[...o[12]||(o[12]=[t("http://www.tecmint.com/who-is-root-why-does-root-exist-in-linux/",-1)])]),_:1})]),e("p",null,[o[17]||(o[17]=t("作者：",-1)),s(r,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...o[14]||(o[14]=[t("Gabriel Cánepa",-1)])]),_:1}),o[18]||(o[18]=t(" 譯者：",-1)),s(r,{href:"https://github.com/zhb127"},{default:n(()=>[...o[15]||(o[15]=[t("zhb127",-1)])]),_:1}),o[19]||(o[19]=t(" 校對：",-1)),s(r,{href:"https://github.com/wxy"},{default:n(()=>[...o[16]||(o[16]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原創編譯，",-1)),s(r,{href:"https://linux.cn/"},{default:n(()=>[...o[21]||(o[21]=[t("Linux中國",-1)])]),_:1}),o[24]||(o[24]=t(" 榮譽推出",-1))])])}const b=d(u,[["render",m]]);export{C as __pageData,b as default};
